// ─────────────────────────────────────────────────────────────────────────────
//  BIBLIOTHÈQUE D'ENTRAÎNEMENTS — base de connaissances du coach IA.
//  Fondée sur la science de l'entraînement (Daniels, Seiler 80/20, Canova,
//  Billat, périodisation). L'IA pioche, sélectionne et ADAPTE selon le client
//  (niveau, objectif, forme, charge, blessures). Chaque séance est un MODÈLE :
//  les allures réelles sont calculées depuis la VMA / les zones du client.
//  Repères d'allure (% VMA) : Z1 récup 55-65 · Z2 endurance 65-75 · Z3 tempo
//  75-85 · seuil 83-88 · Z4 85-92 · VMA/Z5 95-105 · vitesse 105-120.
// ─────────────────────────────────────────────────────────────────────────────

export type WorkoutCategory =
  | "recovery" | "endurance" | "long" | "tempo" | "threshold" | "vo2max"
  | "speed" | "hills" | "race_specific" | "trail" | "strength" | "drills" | "cross" | "test";

export type Level = "debutant" | "intermediaire" | "confirme" | "elite";
export type Goal = "general" | "5k" | "10k" | "semi" | "marathon" | "trail" | "ultra";

export type WorkoutTemplate = {
  id: string;
  name: string;
  category: WorkoutCategory;
  zone: string;            // zone(s) dominante(s)
  purpose: string;         // ce que ça développe / quand l'utiliser
  structure: string;       // modèle (le coach remplit les allures depuis la VMA)
  levels: Level[];
  goals: Goal[];
  durationMin: [number, number];
  scaling: string;         // comment doser selon le niveau / la forme
  injuryNote?: string;
};

export const CATEGORY_LABEL: Record<WorkoutCategory, string> = {
  recovery: "Récupération", endurance: "Endurance", long: "Sortie longue",
  tempo: "Tempo", threshold: "Seuil", vo2max: "VO2max", speed: "Vitesse / économie",
  hills: "Côtes", race_specific: "Allure spécifique course", trail: "Trail spécifique",
  strength: "Renforcement", drills: "Éducatifs / technique", cross: "Cross-training", test: "Test / évaluation",
};

