// ── Sélection + catalogue condensé pour le prompt IA ─────────────────────────
export function pickWorkouts(opts: { level?: Level; goal?: Goal; categories?: WorkoutCategory[] }): WorkoutTemplate[] {
  return WORKOUT_LIBRARY.filter(w =>
    (!opts.level || w.levels.includes(opts.level)) &&
    (!opts.goal || w.goals.includes(opts.goal) || w.goals.includes("general")) &&
    (!opts.categories || opts.categories.includes(w.category))
  );
}

// Catalogue condensé (texte) à injecter dans le prompt : l'IA pioche et adapte.
export function buildSessionCatalog(opts: { level?: Level; goal?: Goal } = {}): string {
  const picked = pickWorkouts(opts);
  const byCat = new Map<WorkoutCategory, WorkoutTemplate[]>();
  for (const w of picked) { const a = byCat.get(w.category) ?? []; a.push(w); byCat.set(w.category, a); }
  const order: WorkoutCategory[] = ["recovery", "endurance", "long", "tempo", "threshold", "vo2max", "speed", "hills", "race_specific", "trail", "strength", "drills", "cross", "test"];
  const lines: string[] = [];
  for (const cat of order) {
    const ws = byCat.get(cat);
    if (!ws?.length) continue;
    lines.push(`• ${CATEGORY_LABEL[cat]} : ${ws.map(w => `${w.name} [${w.structure}]`).join(" ; ")}`);
  }
  return lines.join("\n");
}

export const LIBRARY_COUNT = WORKOUT_LIBRARY.length;
